// Accurate India GIS Map Data (35 States & UTs)
// Conformal projection calibrated to standard Surveyor General of India layout

export interface IndiaStatePath {
  id: string;
  name: string;
  d: string;
  cx: number;
  cy: number;
}

export const INDIA_MAP_VIEWBOX = '0 0 800 900';

export function projectCoord(lat: number, lng: number): [number, number] {
  const cos22 = 0.92718385;
  const scale = 26.5;
  const originLng = 68.0;
  const originLat = 37.5;
  const offsetX = 35.0;
  const offsetY = 35.0;
  const x = (lng - originLng) * cos22 * scale + offsetX;
  const y = (originLat - lat) * scale + offsetY;
  return [Math.round(x * 10) / 10, Math.round(y * 10) / 10];
}

